  g.swap = Math.max(0, g.swap - dt);
  g.pumpT = Math.max(0, g.pumpT - dt);
  g.bloom = Math.max(0, g.bloom - dt * 2.5);
  const adsTarget = adsHeld && g.swap <= 0 && (g.reload <= 0 || w.shell) ? 1 : 0;
  g.ads = clamp(g.ads + (adsTarget ? dt / w.adsT : -dt / (w.adsT * 0.8)), 0, 1);
