        if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
        const col = this.col(cx + dx, cz + dz); if (!col) continue;
        for (const n of col) {
          const d = Math.abs(n.y - y) * 1.5 + (Math.abs(dx) + Math.abs(dz)) * 2;
          if (n.y > y + 3) continue;
          if (d < bd) { bd = d; best = n; }
        }
